@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Course Catalog</PageTitle>

<div class="container">
    <h1>Course Catalog</h1>

    <div class="row mb-4">
        <div class="col-md-6">
            <input type="text" class="form-control" placeholder="Search courses..."
                   @bind="_searchTerm" @bind:event="oninput" @bind:after="ApplyFilters" />
        </div>
        <div class="col-md-4">
            <select class="form-select" @bind="_selectedDepartmentId" @bind:after="ApplyFilters">
                <option value="0">All Departments</option>
                @foreach (var dept in _departments)
                {
                    <option value="@dept.Id">@dept.Name (@dept.Code)</option>
                }
            </select>
        </div>
    </div>

    <p class="text-muted">Showing @_filteredCourses.Count course(s)</p>

    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in _filteredCourses)
                {
                    <tr>
                        <td>@course.FullCode</td>
                        <td>@course.Title</td>
                        <td>@course.Credits</td>
                        <td>@course.InstructorName</td>
                        <td>@course.Schedule</td>
                        <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
</div>

@code {
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<Department> _departments = new();
    private List<Course> _filteredCourses = new();
    private string _searchTerm = string.Empty;
    private int _selectedDepartmentId;

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetDepartments();
        _selectedDepartmentId = DepartmentId ?? 0;
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        _filteredCourses = CatalogService.SearchCourses(
            string.IsNullOrWhiteSpace(_searchTerm) ? null : _searchTerm,
            _selectedDepartmentId > 0 ? _selectedDepartmentId : null);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>@(_course?.Title ?? "Course Not Found")</PageTitle>

<div class="container">
    @if (_course is null)
    {
        <div class="alert alert-warning">Course not found.</div>
        <a href="/courses" class="btn btn-secondary">Back to Catalog</a>
    }
    else
    {
        <nav aria-label="breadcrumb">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/">Home</a></li>
                <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
                <li class="breadcrumb-item active">@_course.FullCode</li>
            </ol>
        </nav>

        <h1>@_course.FullCode — @_course.Title</h1>

        <div class="row mt-4">
            <div class="col-md-8">
                <h4>Description</h4>
                <p>@_course.Description</p>

                <h4 class="mt-4">Schedule</h4>
                <p>@_course.Schedule</p>

                <h4 class="mt-4">Credits</h4>
                <p><span class="badge bg-primary fs-6">@_course.Credits credits</span></p>
            </div>
            <div class="col-md-4">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Instructor</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@_course.InstructorName</h6>
                        <p class="card-text">@_course.InstructorBio</p>
                    </div>
                </div>
                <a href="/enroll?courseId=@_course.Id" class="btn btn-primary w-100 mt-3">Request Enrollment</a>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Course? _course;

    protected override void OnInitialized()
    {
        _course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<div class="container">
    <h1>Enrollment Request</h1>
    <p>Submit this form to request enrollment in a course. You will receive confirmation via your university email.</p>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted!</h4>
            <p>Your enrollment request for <strong>@_selectedCourseTitle</strong> has been received. You will be notified of your enrollment status.</p>
            <a href="/courses" class="btn btn-primary">Browse More Courses</a>
        </div>
    }
    else
    {
        <form method="post" @onsubmit="HandleSubmit" @formname="enrollment">
            <AntiforgeryToken />
            <div class="row">
                <div class="col-md-8">
                    <div class="mb-3">
                        <label for="studentName" class="form-label">Full Name</label>
                        <input type="text" class="form-control" id="studentName" name="StudentName"
                               @bind="_model.StudentName" required />
                    </div>

